import {existsSync,lstatSync,mkdirSync,mkdtempSync,readFileSync,realpathSync,rmSync,symlinkSync,writeFileSync} from 'node:fs';
import {dirname,join} from 'node:path';
import {tmpdir} from 'node:os';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(), work=mkdtempSync(join(root,'.git','b11-decisions-'));
const ownerFile='tests/helpers/owned-test-directory.ts', dbFile='tests/helpers/test-database.ts', testFile='tests/helpers/test-database.test.ts';
const inputs=[ownerFile,dbFile,testFile,'tests/test-setup.ts'].map(path=>({path,sourceHash:sourceHash(readFileSync(path,'utf8'))}));
mkdirSync(join(work,'tests/helpers'),{recursive:true});
symlinkSync(join(root,'src'),join(work,'src'),process.platform==='win32'?'junction':'dir');
writeFileSync(join(work,testFile),readFileSync(testFile));
writeFileSync(join(work,'bunfig.toml'),'[test]\ncoverage = false\ntimeout = 30000\npreload = ['+JSON.stringify(join(root,'tests/test-setup.ts'))+']\n');
const originals=new Map([ownerFile,dbFile].map(path=>[path,readFileSync(path,'utf8')]));
const cases=[
 ['inode',ownerFile,'stat.ino === identity.ino','true','cleanup refuses a replacement directory'],
 ['marker-content',ownerFile,'readFileSync(markerPath,"utf8") !== owner','false','an ownership marker that is'],
 ['marker-links',ownerFile,'marker.nlink !== 1','false','an ownership marker that is'],
 ['directory-completion',ownerFile,'try { io.remove(dir); removed = true; }','try { removed = true; io.remove(dir); }','partial removal restores ownership'],
 ['close-completion',dbFile,'dependencies.close(result.db); closed = true;','closed = true; dependencies.close(result.db);','failed database close retains'],
 ['retry-limit',dbFile,'++attempts >= 3','++attempts >= 4','persistent removal error'],
 ['retry-classification',dbFile,'!isBusyRemoval(error)','false','a non-Error cleanup failure'],
 ['retry-pacing',dbFile,'dependencies.waitBeforeRetry(attempts);','void attempts;','transient busy removal'],
];
const records=[];
for(const [id,path,needle,replacement,pattern] of cases){
 const allocationLog=join(work,id+'-allocations.jsonl');
 for(const [sourcePath,source] of originals){
  let code=source;
  if(sourcePath===path){if(code.split(needle!).length!==2)throw Error('Ambiguous mutation '+id);code=code.replace(needle!,replacement!);}
  if(sourcePath===ownerFile)code=code.replace('let removed = false;','let removed = false;\n  writeFileSync('+JSON.stringify(allocationLog)+',owner+"\\n",{flag:"a"});');
  writeFileSync(join(work,sourcePath),code);
 }
 const result=Bun.spawnSync([process.execPath,'test',testFile,'--test-name-pattern',pattern!],{cwd:work,stdout:'pipe',stderr:'pipe',timeout:20000});
 const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
 const recovery=[];
 if(existsSync(allocationLog))for(const line of readFileSync(allocationLog,'utf8').trim().split('\n')){
  const owner=JSON.parse(line), stat=lstatSync(owner.dir,{bigint:true,throwIfNoEntry:false});
  if(!stat){recovery.push({path:owner.dir,status:'already absent'});continue;}
  const marker=join(owner.dir,'.memory-test-owner.json');
  const ms=lstatSync(marker,{throwIfNoEntry:false});
  if(!stat.isDirectory()||stat.isSymbolicLink()||realpathSync(owner.dir)!==owner.dir||dirname(owner.dir)!==realpathSync(tmpdir())||owner.project!=='memory-nexus'||stat.dev.toString()!==owner.device||stat.ino.toString()!==owner.inode||!ms||!ms.isFile()||ms.isSymbolicLink()||ms.nlink!==1||readFileSync(marker,'utf8')!==line){recovery.push({path:owner.dir,status:'retained - ownership not verified'});continue;}
  rmSync(owner.dir,{recursive:true,force:false});recovery.push({path:owner.dir,status:'reclaimed after process exit and ownership verification'});
 }
 const killed=result.exitCode===1&&output.includes('(fail)')&&output.includes('expect(');
 records.push({id,path,needle,replacement,pattern,exit:result.exitCode,status:killed?'KILLED':'UNRESOLVED',output,recovery});
 console.log(JSON.stringify({id,exit:result.exitCode,status:killed?'KILLED':'UNRESOLVED',retained:recovery.filter(x=>x.status.startsWith('retained')).length}));
}
for(const [path,source] of originals)writeFileSync(join(work,path),source);
writeFileSync('.git/b11-decision-mutations.json',JSON.stringify({sourceInputs:inputs,cwd:work,runtime:Bun.version,records,probeSource:readFileSync('.git/b11-decision-mutations.ts','utf8'),scope:'Eight deliberate faults in isolated generated helper copies; original source remains untouched. Allocations are logged for identity-verified recovery after each child exits. Not exhaustive mutation or review acceptance.'},null,2)+'\n');
if(records.some(x=>x.status!=='KILLED'||x.recovery.some(r=>r.status.startsWith('retained'))))process.exitCode=1;
